components.css:
.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
    padding: 10px 16px; border: 1px solid transparent; border-radius: 9px;
    font: 680 14px / 1.35 var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif); cursor: pointer; text-align: center;
  background: var(--accent, #5736c5); color: white;
}
.ds-button-primary:hover { background: var(--accent-hover, #4423a7); }
.ds-button-primary:focus-visible { outline: 2px solid var(--accent, #5736c5); outline-offset: 3px; }
.ds-button-primary:disabled { cursor: not-allowed; opacity: 0.55; }

.ds-button-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
    padding: 10px 16px; border: 1px solid transparent; border-radius: 9px;
    font: 680 14px / 1.35 var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif); cursor: pointer; text-align: center;
  background: var(--surface, #fff); color: var(--ink, #261b3d);
  border-color: var(--control, #9586aa);
}
.ds-button-secondary:hover { background: var(--wash, #eee9ff); }
.ds-button-secondary:focus-visible { outline: 2px solid var(--accent, #5736c5); outline-offset: 3px; }
.ds-button-secondary:disabled { cursor: not-allowed; opacity: 0.55; }

.ds-button-text {
  display: inline-flex; align-items: center; gap: 7px; min-height: 40px; padding: 4px 0; border: 0;
  color: var(--accent, #5736c5); background: transparent; font: 650 13px var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
  text-decoration: none; text-underline-offset: 0.2em;
}
.ds-button-text:hover { text-decoration: underline; }
.ds-button-text:focus-visible { outline: 2px solid var(--accent, #5736c5); outline-offset: 3px; }

.ds-button-danger { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
    padding: 10px 16px; border: 1px solid transparent; border-radius: 9px;
    font: 680 14px / 1.35 var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif); cursor: pointer; text-align: center;
  background: var(--red, #a62c48); color: white;
}
.ds-button-danger:hover { background: #8d223a; }
.ds-button-danger:focus-visible { outline: 2px solid var(--accent, #5736c5); outline-offset: 3px; }
.ds-button-danger:disabled { cursor: not-allowed; opacity: 0.55; }

.ds-field {
  display: grid; gap: 7px; min-width: 0; margin-block: 17px;
  color: var(--ink, #261b3d); font: 650 14px var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
}
.ds-field input {
  box-sizing: border-box; min-width: 0; width: 100%; min-height: 44px; padding: 9px 11px;
  border: 1px solid var(--control, #9586aa); border-radius: 8px; background: var(--surface, #fff);
  color: var(--ink, #261b3d); font: 460 15px var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
  caret-color: var(--accent, #5736c5);
}
.ds-field input:focus-visible { outline: 2px solid var(--accent, #5736c5); outline-offset: 3px; }
.ds-field input:disabled { background: var(--paper, #f7f6fb); opacity: 0.75; }

.ds-studio-nav { display: grid; gap: 4px; }
.ds-studio-link {
  display: flex; align-items: center; gap: 10px; min-height: 44px; box-sizing: border-box;
  padding: 9px 11px; border-radius: 8px; color: var(--muted, #615871);
  font: 610 14px var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif); text-decoration: none;
}
.ds-studio-link svg { flex-shrink: 0; }
.ds-studio-link:hover { background: var(--paper, #f7f6fb); color: var(--ink, #261b3d); }
.ds-studio-link[aria-current] { background: var(--wash, #eee9ff); color: var(--accent-hover, #4423a7); font-weight: 720; }
.ds-studio-link:focus-visible { outline: 2px solid var(--accent, #5736c5); outline-offset: 3px; }
@media (max-width: 820px) {
  .ds-studio-nav { display: flex; flex-wrap: wrap; }
  .ds-studio-link { padding: 5px 9px; min-height: 39px; gap: 6px; font-size: 13px; }
  .ds-studio-link svg { width: 16px; }
}

.ds-status {
  display: inline-block; padding: 4px 9px; border-radius: 6px; background: var(--wash, #eee9ff);
  color: var(--accent-hover, #4423a7); font: 660 12px / 1.35 var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
}
.ds-status::first-letter { text-transform: uppercase; }
@media (max-width: 370px) {
  .ds-status { padding-inline: 6px; font-size: 11px; }
}

.ds-preview-panel {
  min-width: 0; padding: 15px; border: 1px solid var(--line, #e1dbea); border-radius: 12px;
  color: var(--ink, #261b3d); background: var(--surface, #fff); font-family: var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
}
.ds-preview-panel h2 { margin: 0; font-size: 1.25rem; font-weight: 700; line-height: 1.22; letter-spacing: -0.023em; }
.ds-player-frame {
  position: relative; display: grid; grid-template-rows: 1fr auto; min-height: 154px; align-items: center; overflow: hidden;
  margin-block: 13px 15px; border-radius: 9px; background: var(--stage, #302349);
}
.ds-preview-placeholder {
  display: grid; justify-items: center; align-content: center; gap: 7px; padding: 17px 12px; text-align: center;
}
.ds-preview-placeholder small { color: var(--stage-accent, #dbcaff); font-size: 13px; line-height: 1.55; }
.ds-choose-recording {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
  padding: 10px 16px; border: 1px solid var(--control, #9586aa); border-radius: 9px; color: var(--ink, #261b3d);
  background: var(--surface, #fff); font-family: inherit; font-size: 14px; font-weight: 680; line-height: 1.35; cursor: pointer; text-align: center;
}
.ds-choose-recording:hover { background: var(--wash, #eee9ff); }
.ds-choose-recording:focus-visible { outline: 2px solid var(--accent, #5736c5); outline-offset: 3px; }
.ds-local-caption { display: grid; justify-items: center; margin: 0 10px 11px; pointer-events: none; }
.ds-local-caption p {
  margin: 0; max-width: 100%; max-height: 6rem; overflow: hidden; padding: 4px 9px; border-radius: 4px;
  background: #1f152c; color: white; text-align: center; font-size: 18px; line-height: 2.06;
  text-shadow: 0 1px 3px #120b1a; white-space: pre-line; overflow-wrap: anywhere;
}
@media (max-width: 660px) {
  .ds-preview-panel { padding: 12px; }
}

.ds-format-stage {
  padding: 12px; border-radius: 16px; background: var(--stage, #302349); font-family: var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
  --frame-line: #4e436b; --frame-text: #f9f6ff; --frame-soft: #d9cee9;
}
.ds-format-selector {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px;
  padding: 4px; margin: 0; min-inline-size: 0; border: 1px solid var(--frame-line); border-radius: 10px;
}
.ds-format-selector label { position: relative; }
.ds-format-selector span {
  display: grid; place-items: center; min-height: 34px; padding: 4px 13px; box-sizing: border-box;
  border-radius: 6px; text-align: center; cursor: pointer; line-height: 1.2; font-size: 13px;
  font-weight: 650; color: var(--frame-soft);
}
.ds-format-selector label:hover span { background: #ffffff13; color: var(--frame-text); }
.ds-format-selector input:checked + span { background: var(--stage-accent, #dbcaff); color: var(--stage, #302349); }
.ds-format-selector input:focus-visible + span { outline: 2px solid var(--stage-accent, #dbcaff); outline-offset: 2px; }
.ds-visually-hidden {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap; border: 0;
}
@media (max-width: 560px) {
  .ds-format-selector span { padding-inline: 3px; font-size: 12px; }
}
@media (max-width: 360px) {
  .ds-format-selector { grid-template-columns: 0.85fr 1.25fr 0.9fr 1fr; }
  .ds-format-selector span { font-size: 11px; }
}

.ds-caption-frame {
  position: relative; aspect-ratio: 16 / 8.8; width: 100%; overflow: hidden;
  border-radius: 10px; background: #23182c; font-family: var(--body, "Public Sans Variable", CaptionUrdu, Arial, sans-serif);
}
.ds-caption-lines {
  position: absolute; inset: auto 9px clamp(12px, 5%, 28px); display: grid;
  justify-items: center; gap: 4px; text-align: center;
}
.ds-caption-lines span {
  padding: 4px 10px; border-radius: 4px; background: #1b1128; color: #fff;
  font-size: clamp(0.825rem, 1.45vw, 1.35rem); font-weight: 650; line-height: 1.38;
}
.ds-caption-lines span:lang(ur) {
  padding: 2px 12px 6px; font-family: CaptionUrdu, serif; font-size: clamp(1.05rem, 2.2vw, 2rem);
  font-weight: 400; line-height: 2.08; color: var(--stage, #302349); background: var(--stage-accent, #dbcaff);
}
@media (max-width: 560px) {
  .ds-caption-frame { aspect-ratio: 16 / 9.5; }
}
